// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address recipient = address(new RevertingRecipient());

        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.getFirstWithdrawalBonus.selector, recipient));

        assertTrue(!ok, "Expected revert due to failed call");
    }
}

contract RevertingRecipient {
    receive() external payable {
        revert("I reject ether");
    }
}
